CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,customer_account_id uuid REFERENCES users(id),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','pending','held','review','confirmed','expired','rejected','cancelled','checked_in','checked_out')),starts_on date NOT NULL,ends_on date CHECK(ends_on>starts_on),version integer NOT NULL DEFAULT 1 CHECK(version>0),pricing_snapshot jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,property_id,room_id,id),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id),CHECK(state IN ('draft','pending','expired','rejected','cancelled') OR pricing_snapshot IS NOT NULL));
CREATE TABLE leases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,booking_id uuid NOT NULL UNIQUE,state text NOT NULL DEFAULT 'preparing' CHECK(state IN ('preparing','checked_in','physical_exit','closed')),starts_on date NOT NULL,planned_end_on date CHECK(planned_end_on>starts_on),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),UNIQUE(organization_id,property_id,room_id,id),FOREIGN KEY(organization_id,property_id,room_id,booking_id) REFERENCES bookings(organization_id,property_id,room_id,id));
CREATE TABLE room_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,starts_on date NOT NULL,ends_on date CHECK(ends_on>starts_on),reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','released')),version integer NOT NULL DEFAULT 1 CHECK(version>0),actor_id uuid NOT NULL REFERENCES users(id),released_by uuid REFERENCES users(id),release_reason text,created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,UNIQUE(organization_id,property_id,room_id,id),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id),CHECK((state='active' AND released_at IS NULL AND released_by IS NULL AND release_reason IS NULL) OR(state='released' AND released_at IS NOT NULL AND released_by IS NOT NULL AND length(trim(release_reason)) BETWEEN 3 AND 1000)));
CREATE TABLE room_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('hold','stay','block')),state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','released')),starts_on date NOT NULL,ends_on date CHECK(ends_on>starts_on),booking_id uuid,lease_id uuid,block_id uuid,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id,room_id,booking_id) REFERENCES bookings(organization_id,property_id,room_id,id),FOREIGN KEY(organization_id,lease_id) REFERENCES leases(organization_id,id),FOREIGN KEY(organization_id,property_id,room_id,block_id) REFERENCES room_blocks(organization_id,property_id,room_id,id),CHECK((kind='block' AND block_id IS NOT NULL AND booking_id IS NULL AND lease_id IS NULL) OR(kind='hold' AND booking_id IS NOT NULL AND block_id IS NULL AND lease_id IS NULL) OR(kind='stay' AND block_id IS NULL AND num_nonnulls(booking_id,lease_id)=1)),CHECK((state='active' AND released_at IS NULL) OR(state='released' AND released_at IS NOT NULL)),EXCLUDE USING gist(organization_id WITH =,room_id WITH =,daterange(starts_on,ends_on,'[)') WITH &&) WHERE(state='active'));
CREATE UNIQUE INDEX block_one_allocation ON room_allocations(block_id) WHERE block_id IS NOT NULL;
CREATE UNIQUE INDEX booking_one_active_allocation ON room_allocations(booking_id) WHERE state='active' AND booking_id IS NOT NULL;
CREATE UNIQUE INDEX lease_one_active_allocation ON room_allocations(lease_id) WHERE state='active' AND lease_id IS NOT NULL;
CREATE INDEX allocations_property_page ON room_allocations(organization_id,property_id,id);
CREATE TABLE room_presence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,lease_id uuid NOT NULL,entered_at timestamptz NOT NULL,exited_at timestamptz CHECK(exited_at>=entered_at),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id),FOREIGN KEY(organization_id,lease_id) REFERENCES leases(organization_id,id));
CREATE UNIQUE INDEX room_one_active_presence ON room_presence(organization_id,room_id) WHERE exited_at IS NULL;
CREATE UNIQUE INDEX lease_one_active_presence ON room_presence(organization_id,lease_id) WHERE exited_at IS NULL;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bookings','leases','room_blocks','room_allocations','room_presence'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scoped_read ON %I FOR SELECT TO kost_app USING(organization_id=current_org() AND can_access_location(organization_id,property_id))',t);END LOOP;END $$;
GRANT SELECT ON room_blocks,room_allocations,room_presence TO kost_app;
-- Booking/lease are schema foundations, no runtime grants/commands until identity/invoice prerequisites.
CREATE POLICY block_insert ON room_blocks FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id) AND actor_id=current_actor());
CREATE POLICY block_release ON room_blocks FOR UPDATE TO kost_app USING(can_manage_inventory(organization_id,property_id)) WITH CHECK(can_manage_inventory(organization_id,property_id));
CREATE POLICY allocation_block_insert ON room_allocations FOR INSERT TO kost_app WITH CHECK(kind='block' AND can_manage_inventory(organization_id,property_id));
CREATE POLICY allocation_block_release ON room_allocations FOR UPDATE TO kost_app USING(kind='block' AND can_manage_inventory(organization_id,property_id)) WITH CHECK(kind='block' AND can_manage_inventory(organization_id,property_id));
GRANT INSERT ON room_blocks,room_allocations TO kost_app;
GRANT UPDATE(state,version,released_by,release_reason,released_at) ON room_blocks TO kost_app;
GRANT UPDATE(state,version,released_at) ON room_allocations TO kost_app;
CREATE FUNCTION check_block_allocation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE b public.room_blocks%ROWTYPE;bid uuid;BEGIN bid=CASE WHEN TG_TABLE_NAME='room_blocks' THEN NEW.id ELSE NEW.block_id END;IF bid IS NULL THEN RETURN NULL;END IF;SELECT * INTO b FROM public.room_blocks WHERE id=bid;IF NOT EXISTS(SELECT 1 FROM public.room_allocations a WHERE a.block_id=b.id AND a.organization_id=b.organization_id AND a.property_id=b.property_id AND a.room_id=b.room_id AND a.state=b.state AND a.starts_on=b.starts_on AND a.ends_on IS NOT DISTINCT FROM b.ends_on) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;RETURN NULL;END $$;
REVOKE ALL ON FUNCTION check_block_allocation() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER block_allocation_consistent AFTER INSERT OR UPDATE ON room_blocks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_block_allocation();
CREATE CONSTRAINT TRIGGER allocation_block_consistent AFTER INSERT OR UPDATE ON room_allocations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_block_allocation();
CREATE FUNCTION guard_block_release() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.state<>'active' OR NEW.state<>'released' OR NEW.version<>OLD.version+1 OR NEW.released_by IS DISTINCT FROM current_actor() THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;
CREATE TRIGGER block_release_guard BEFORE UPDATE ON room_blocks FOR EACH ROW EXECUTE FUNCTION guard_block_release();
